timeout 10 python3 - <<'EOF'
from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_event_newlines():
    try:
        ServerSentEvent(event="event1\nevent2")
        print("Failed: allowed newline in event")
    except ValidationError as e:
        print("Passed: caught newline in event")

def test_id_newlines():
    try:
        ServerSentEvent(id="id1\nid2")
        print("Failed: allowed newline in id")
    except ValidationError as e:
        print("Passed: caught newline in id")

def test_id_null():
    try:
        ServerSentEvent(id="id1\0id2")
        print("Failed: allowed null in id")
    except ValidationError as e:
        print("Passed: caught null in id")

def test_valid():
    try:
        ServerSentEvent(event="event1", id="id1")
        print("Passed: allowed valid event and id")
    except ValidationError as e:
        print("Failed: rejected valid event and id", e)

test_event_newlines()
test_id_newlines()
test_id_null()
test_valid()
EOF

